package dev.eugheist.tc4modern;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class OuterBossAudit {
 static int ticks;static volatile String failed;static volatile boolean warming,loaded,warm,prepared;static final BlockPos BASE=new BlockPos(Integer.getInteger("tc4modern.outerBossAuditX",1020),121,-90);
 static void check(boolean b,String message){if(!b)failed=message;System.out.println("TC4_OUTER_BOSS "+(b?"PASS ":"FAIL ")+message);}
 static EldritchGolem golem(ServerPlayer player,double x){var level=player.serverLevel();var golem=OuterBossContent.GOLEM.get().create(level);golem.moveTo(x,BASE.getY(),BASE.getZ()+2,180,0);golem.getAttribute(Champions.MOD).setBaseValue(-1);golem.setNoAi(true);level.addFreshEntity(golem);return golem;}
 static void setup(ServerPlayer player){
  var level=player.server.overworld();player.teleportTo(level,BASE.getX()+.5,BASE.getY()+1,BASE.getZ()-6,0,0);player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);player.getAbilities().flying=true;player.onUpdateAbilities();player.getInventory().clearContent();player.containerMenu.broadcastChanges();level.setDayTime(13000);level.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,level.getServer());
  for(int x=-8;x<=8;x++)for(int z=-5;z<=8;z++){level.setBlock(BASE.offset(x,-1,z),Blocks.GLOWSTONE.defaultBlockState(),3);for(int y=0;y<=7;y++)level.setBlock(BASE.offset(x,y,z),Blocks.AIR.defaultBlockState(),2);}
  var place=BASE.offset(0,-1,-3);var placer=new net.minecraft.world.item.ItemStack(LeaderGear.item("obelisk_placer"));player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,placer);var use=new net.minecraft.world.item.context.UseOnContext(player,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(place.getCenter(),net.minecraft.core.Direction.UP,place,false));var placed=placer.getItem().onItemUseFirst(placer,use);check(placed.consumesAction()&&level.getBlockEntity(place.above()) instanceof CrimsonAltarEntity&&level.getBlockState(place.above(7)).is(CrimsonContent.OBELISK_BODY.get())&&placer.getCount()==1,"original creative placer builds obelisk without consuming item");check(!level.getBlockState(place.above(7)).hasBlockEntity(),"obelisk body has no block entity as in original metadata two");level.removeBlock(place.above(),false);check(level.isEmptyBlock(place.above(3))&&level.isEmptyBlock(place.above(7)),"breaking obelisk cascades through body blocks");player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,net.minecraft.world.item.ItemStack.EMPTY);
  var normal=golem(player,BASE.getX()-3);check(normal.getMaxHealth()==250&&normal.getArmorValue()==6&&normal.getAttributeBaseValue(Attributes.ATTACK_DAMAGE)==10,"golem original 250 health, six armour, ten damage");
  normal.hurt(level.damageSources().playerAttack(player),40);check(normal.anger()==200&&250-normal.getHealth()<=35,"shared boss enrage and 35 damage cap");normal.removeAllEffects();normal.invulnerableTime=0;normal.setHealth(250);
  var headless=golem(player,BASE.getX()+3);headless.setHealth(200);boolean hit=headless.hurt(level.damageSources().playerAttack(player),201);check(!hit&&headless.isHeadless()&&headless.spawnTimer()==100&&headless.getHealth()==200,"lethal blow removes head instead of killing golem");
  for(int i=0;i<100;i++)headless.tick();check(headless.getHealth()==250&&headless.spawnTimer()==0,"second stage heals during original 100-tick immunity");
  for(int i=100;i<150;i++)headless.tick();check(headless.beamCharge==150&&!headless.chargingBeam,"headless cannon recharges for 150 ticks");
  var target=EntityType.ZOMBIE.create(level);target.moveTo(BASE.getX()+3,BASE.getY(),BASE.getZ()+9,0,0);target.getAttribute(Champions.MOD).setBaseValue(-1);target.setNoAi(true);level.addFreshEntity(target);
  int before=level.getEntitiesOfClass(GolemOrb.class,headless.getBoundingBox().inflate(32)).size();headless.performRangedAttack(target,1);check(headless.beamCharge>=131&&headless.beamCharge<=135&&level.getEntitiesOfClass(GolemOrb.class,headless.getBoundingBox().inflate(32)).size()==before+1,"headless cannon fires original homing orb and consumes 15..19 charge");target.discard();level.getEntitiesOfClass(GolemOrb.class,headless.getBoundingBox().inflate(32)).forEach(Entity::discard);
  var tag=new net.minecraft.nbt.CompoundTag();headless.saveWithoutId(tag);var copy=OuterBossContent.GOLEM.get().create(level);copy.load(tag);check(copy.isHeadless()&&copy.getMaxHealth()==250,"headless phase survives save/load");
  var home=BASE.offset(3,0,2);headless.restrictTo(home,24);headless.saveWithoutId(tag);copy.load(tag);check(copy.hasRestriction()&&copy.getRestrictCenter().equals(home)&&copy.getRestrictRadius()==24,"boss home survives save/load");
  headless.moveTo(BASE.getX()+3,BASE.getY(),BASE.getZ()+2,180,0);headless.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);
 }
 static void warden(ServerPlayer player){var level=player.serverLevel();var w=OuterBossContent.WARDEN.get().create(level);w.moveTo(BASE.getX()+.5,BASE.getY(),BASE.getZ()+5,180,0);w.getAttribute(Champions.MOD).setBaseValue(-1);w.setNoAi(true);w.finalizeSpawn(level,level.getCurrentDifficultyAt(w.blockPosition()),MobSpawnType.COMMAND,null);level.addFreshEntity(w);
  check(w.getMaxHealth()==200&&w.getArmorValue()==4&&w.getAttributeBaseValue(Attributes.ATTACK_DAMAGE)==10,"warden original 200 health, four armour, ten damage");check(w.getAbsorptionAmount()==132&&w.spawnTimer()==150,"warden spawns with original 132 shield and 150-tick emergence");
  w.spawnTimer=0;w.setAbsorptionAmount(0);w.hurt(level.damageSources().playerAttack(player),1);check(w.fieldFrenzyCounter==150&&w.fieldFrenzy,"shield depletion activates one field frenzy");w.invulnerableTime=0;check(!w.hurt(level.damageSources().playerAttack(player),1),"warden immune during field frenzy");
  w.fieldFrenzyCounter=120;w.performFieldFrenzy();int fields=0;for(var pos:BlockPos.betweenClosed(BASE.offset(-8,0,-5),BASE.offset(8,0,8)))if(level.getBlockState(pos).is(OuterHazard.BLOCK.get()))fields++;check(fields>5&&w.fieldFrenzyCounter==119,"warden expands original timed field ring: "+fields+" blocks");w.fieldFrenzyCounter=0;
  w.tickCount=25;w.invulnerableTime=0;w.tick();check(w.getAbsorptionAmount()==1,"warden regenerates one shield each 25 ticks");
  var target=EntityType.ZOMBIE.create(level);target.moveTo(w.getX(),w.getY(),w.getZ()+3,0,0);target.setNoAi(true);target.getAttribute(Champions.MOD).setBaseValue(-1);level.addFreshEntity(target);w.getRandom().setSeed(4096);w.performRangedAttack(target,1);check(target.hasEffect(net.minecraft.world.effect.MobEffects.WITHER)&&target.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)&&target.getDeltaMovement().lengthSqr()>1,"warden sonic inflicts original wither, weakness and knockback");
  var field=OuterHazard.BLOCK.get().defaultBlockState();var initial=target.getDeltaMovement();target.removeAllEffects();target.setDeltaMovement(1,0,1);field.entityInside(level,w.blockPosition(),target);check(target.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)&&Math.abs(target.getDeltaMovement().x-.66)<1e-8,"eldritch field weakens and slows visitors");w.removeAllEffects();field.entityInside(level,w.blockPosition(),w);check(!w.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS),"eldritch mobs immune to their field");target.discard();
  var n=new net.minecraft.nbt.CompoundTag();w.saveWithoutId(n);var copy=OuterBossContent.WARDEN.get().create(level);copy.load(n);check(copy.title().equals(w.title())&&copy.getAbsorptionAmount()==1,"warden title and shield survive NBT");check(!w.getName().getString().contains("%s"),"boss names resolve original format arguments");
 }
 static void cult(ServerPlayer player){var level=player.serverLevel();var leader=OuterBossContent.LEADER.get().create(level);leader.moveTo(BASE.getX()-5,BASE.getY(),BASE.getZ(),0,0);leader.getAttribute(Champions.MOD).setBaseValue(-1);leader.finalizeSpawn(level,level.getCurrentDifficultyAt(leader.blockPosition()),MobSpawnType.COMMAND,null);leader.setNoAi(true);level.addFreshEntity(leader);
  check(leader.getMaxHealth()==125&&leader.getAttributeBaseValue(Attributes.ATTACK_DAMAGE)==5,"cult leader original health and melee attributes");check(leader.getItemBySlot(EquipmentSlot.HEAD).is(LeaderGear.item("cultist_leader_helmet"))&&leader.getItemBySlot(EquipmentSlot.CHEST).is(LeaderGear.item("cultist_leader_chestplate")),"leader equips original fortress-grade armour");check(!leader.getName().getString().contains("%s"),"cult leader title resolves original name arguments");
  var portal=OuterBossContent.PORTAL.get().create(level);portal.moveTo(BASE.getX()+5,BASE.getY(),BASE.getZ(),0,0);level.addFreshEntity(portal);check(portal.getMaxHealth()==500&&portal.getArmorValue()==5,"cult portal original 500 health and five armour");portal.setHealth(400);portal.tick();check(portal.getHealth()==401,"portal regenerates before stage twelve");var before=portal.position();portal.move(MoverType.SELF,new net.minecraft.world.phys.Vec3(1,1,1));check(portal.position().equals(before),"cult portal remains stationary");
  check(level.isPositionEntityTicking(portal.blockPosition()),"cult portal entity section loaded before immediate minion queries");
  portal.stagecounter=0;portal.tick();check(portal.stage==1&&portal.timing()>=20,"cult portal starts invasion with a cultist stage="+portal.stage+" timing="+portal.timing());portal.stage=12;portal.stagecounter=0;int leaders=level.getEntitiesOfClass(CultistLeader.class,portal.getBoundingBox().inflate(32)).size();portal.tick();check(portal.stage==13&&level.getEntitiesOfClass(CultistLeader.class,portal.getBoundingBox().inflate(32)).size()==leaders+1,"stage twelve summons cult leader");
  var tag=new net.minecraft.nbt.CompoundTag();portal.saveWithoutId(tag);var copy=OuterBossContent.PORTAL.get().create(level);copy.load(tag);check(copy.stage==13&&copy.stagecounter==200,"portal persists stage and resets original preparation timer");level.getEntitiesOfClass(CultistEntity.class,portal.getBoundingBox().inflate(32)).forEach(Entity::discard);level.getEntitiesOfClass(CultistLeader.class,portal.getBoundingBox().inflate(32)).stream().filter(e->e!=leader).forEach(Entity::discard);portal.stagecounter=10000;
 }
 @SubscribeEvent static void warm(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.outerBossAuditOnly")||!loaded||warm)return;var level=e.getServer().overworld();if(level.isPositionEntityTicking(BASE)&&level.isPositionEntityTicking(BASE.east(6)))warm=true;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.outerBossAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null||warming&&!warm||ticks>=100&&!prepared)return;ticks++;if(ticks<210)for(var entity:mc.level.entitiesForRendering())if(entity instanceof ThaumcraftBoss boss){boss.setYRot(180);boss.yBodyRot=boss.yBodyRotO=180;boss.yHeadRot=boss.yHeadRotO=180;}// Warm entity sections before spawning and immediately querying minions, even after a dimension change.
 if(ticks==40){warming=true;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();server.execute(()->{var level=server.overworld();for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)level.setChunkForced((BASE.getX()>>4)+x,(BASE.getZ()>>4)+z,true);server.getPlayerList().getPlayer(id).teleportTo(level,BASE.getX()+.5,BASE.getY()+1,BASE.getZ()-6,0,0);loaded=true;});}
 if(ticks==100){var server=mc.getSingleplayerServer();var id=mc.player.getUUID();server.execute(()->{try{setup(server.getPlayerList().getPlayer(id));warden(server.getPlayerList().getPlayer(id));cult(server.getPlayerList().getPlayer(id));}catch(Throwable ex){failed=ex.toString();ex.printStackTrace();}finally{prepared=true;}});}if(ticks==200)LiquidDeathAudit.shot(mc,"outer-golem-boss.png");if(ticks==220){var server=mc.getSingleplayerServer();var id=mc.player.getUUID();server.execute(()->{var level=server.overworld();var at=BASE.offset(25,1,0);level.setBlockAndUpdate(at,OuterGate.LOCK.get().defaultBlockState());server.getPlayerList().getPlayer(id).teleportTo(level,at.getX()+.5,at.getY()+.5,at.getZ()-7,0,0);});}if(ticks==245)LiquidDeathAudit.shot(mc,"outer-lock.png");if(ticks==260){System.out.println(failed==null?"TC4_OUTER_BOSS ALL PASS":"TC4_OUTER_BOSS FAILED "+failed);mc.stop();}}
}
